/* ---------- Portugal : régions approfondies ---------- */
const D53 = [
{ id:'bacalhau-a-gomes-de-sa', c:'eu', lat:41.150, lon:-8.610, base:6, prep:35, cook:40, diff:2, tags:['sea','bake','sunday'],
  art:{v:'plate',bg:'#2f3326',plate:'#f4ecd8',style:'stew',food:['#f0e8d0','#e8c46a','#e0b45a','#4f6f3a'],garnish:'#7fae6a'},
  n:{fr:'Bacalhau à Gomes de Sá',en:'Bacalhau à Gomes de Sá'},
  p:{fr:'Porto, Portugal',en:'Porto, Portugal'},
  d:{fr:"De la morue effeuillée, des pommes de terre et de l'oignon, gratinés à l'huile d'olive avec de l'olive noire et de l'œuf dur. José Luís Gomes de Sá vendait la morue à Porto ; il légua sa recette avec la mention « ne changez rien ».",
     en:"Flaked salt cod, potatoes and onion, gratinated in olive oil with black olives and hard-boiled egg. José Luís Gomes de Sá traded cod in Porto; he bequeathed the recipe with the note 'change nothing'."},
  i:[['salt_cod',800,'g'],['potato',1,'kg'],['onion',600,'g'],['garlic',6,'clove'],['whole_milk',500,'ml'],['olive_oil',180,'ml'],['black_olives',150,'g'],['egg',4,'pc'],['bay_leaf',2,'pc'],['parsley',4,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites dessaler la morue 36 heures à l'eau froide, en changeant l'eau six fois.","Pochez-la 10 minutes puis laissez-la tiédir dans le lait chaud une heure : c'est cette étape qui l'attendrit et la rend crémeuse.","Effeuillez-la à la main en gros pétales, en retirant peau et arêtes.","Faites cuire les pommes de terre en robe des champs, pelez-les tièdes et coupez-les en rondelles épaisses.","Faites fondre l'oignon en lamelles dans l'huile d'olive avec l'ail, mêlez tout dans un plat de terre et enfournez 25 minutes à 200 °C. Garnissez d'œuf dur, d'olives et de persil."],
     en:["Soak the cod for 36 hours in cold water, changing it six times.","Poach it for 10 minutes then let it stand in hot milk for an hour: this is what makes it tender and creamy.","Flake it by hand into large petals, removing skin and bones.","Boil the potatoes in their skins, peel them warm and cut into thick rounds.","Soften the sliced onion in olive oil with the garlic, combine everything in an earthenware dish and bake for 25 minutes at 200°C. Garnish with hard-boiled egg, olives and parsley."]} },

{ id:'bacalhau-a-lagareiro', c:'eu', lat:40.208, lon:-8.429, base:4, prep:25, cook:50, diff:1, tags:['sea','bake','sunday'],
  art:{v:'plate',bg:'#2f3326',plate:'#f4ecd8',style:'fish',food:['#f0e8d0','#e8c46a','#4f6f3a','#e0b45a'],garnish:'#7fae6a'},
  n:{fr:'Bacalhau à lagareiro',en:'Bacalhau à lagareiro'},
  p:{fr:'Coimbra, Beira Litoral, Portugal',en:'Coimbra, Beira Litoral, Portugal'},
  d:{fr:"Un dos de morue rôti sous une pluie d'huile d'olive, avec des pommes de terre écrasées du poing. Lagareiro désigne l'homme du moulin à huile : le plat est là pour goûter l'huile, la morue lui sert de prétexte.",
     en:"A loin of salt cod roasted under a rain of olive oil, with potatoes crushed by fist. Lagareiro means the man at the oil mill: the dish exists to taste the oil, and the cod is its pretext."},
  i:[['salt_cod',4,'pc'],['baby_potatoes',1,'kg'],['garlic',12,'clove'],['olive_oil',300,'ml'],['onion',2,'pc'],['bay_leaf',2,'pc'],['parsley',4,'tbsp'],['coarse_salt',3,'tbsp'],['pepper',null,'']],
  s:{fr:["Faites dessaler les dos de morue 36 heures, puis épongez-les soigneusement.","Faites cuire les pommes de terre entières, non pelées, dans une eau très salée, 25 minutes.","Écrasez-les du poing ou avec le plat de la main, sans les défaire : la peau doit se fendre et la chair rester en morceaux.","Rangez morue et pommes de terre dans un plat de terre, couvrez d'ail en lamelles et d'oignon.","Noyez sous l'huile d'olive — la moitié du plat, sans exagérer le mot — et enfournez 35 minutes à 200 °C."],
     en:["Soak the cod loins for 36 hours, then pat them thoroughly dry.","Boil the potatoes whole and unpeeled in heavily salted water for 25 minutes.","Crush them with your fist or the flat of your hand, without breaking them up: the skin should split and the flesh stay in pieces.","Lay the cod and potatoes in an earthenware dish, cover with sliced garlic and onion.","Drown it in olive oil — half the dish, and that is not an exaggeration — and bake for 35 minutes at 200°C."]} },

{ id:'feijoada-de-buzios', c:'eu', lat:37.017, lon:-7.930, base:6, prep:30, cook:90, diff:2, tags:['sea','legume','comfort'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#8f6a4a','#c9402c','#e0913a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Feijoada de búzios',en:'Whelk feijoada'},
  p:{fr:'Olhão, Algarve, Portugal',en:'Olhão, Algarve, Portugal'},
  d:{fr:"Des bulots mijotés avec des haricots blancs, du chorizo et de la coriandre. L'Algarve fait sa feijoada à la mer : les coquillages remplacent le porc, et la coriandre s'ajoute par poignées entières.",
     en:"Whelks stewed with white beans, chouriço and coriander. The Algarve makes its feijoada from the sea: shellfish replace the pork, and coriander goes in by the handful."},
  i:[['whelks',1.5,'kg'],['white_beans',400,'g'],['chourico',200,'g'],['onion',3,'pc'],['garlic',8,'clove'],['ripe_tomato',400,'g'],['red_pepper',1,'pc'],['cilantro',2,'bunch'],['olive_oil',100,'ml'],['bay_leaf',2,'pc'],['piri_piri',2,'pc'],['white_wine',150,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites dégorger les bulots 2 heures à l'eau salée, puis cuisez-les 25 minutes et retirez-les de leur coquille.","Ôtez l'opercule et la partie noire du bout : c'est la seule partie amère du coquillage.","Faites tremper les haricots une nuit et cuisez-les 50 minutes avec le laurier.","Faites un refogado d'oignon, d'ail, de poivron et de tomate à l'huile d'olive, 20 minutes.","Réunissez haricots, bulots et chorizo, mouillez de vin blanc et laissez 20 minutes. Couvrez de coriandre hors du feu."],
     en:["Purge the whelks for 2 hours in salted water, then boil them for 25 minutes and pull them from their shells.","Remove the operculum and the black tip: it is the only bitter part of the shellfish.","Soak the beans overnight and cook them for 50 minutes with the bay.","Make a refogado of onion, garlic, pepper and tomato in olive oil, 20 minutes.","Bring together the beans, whelks and chouriço, add white wine and give it 20 minutes. Cover with coriander off the heat."]} },

{ id:'frango-a-cafreal', c:'eu', lat:38.708, lon:-9.136, base:4, prep:30, cook:45, diff:2, tags:['poultry','grill','spicy'],
  art:{v:'board',bg:'#33251c',plate:'#f2e6c8',style:'grill',food:['#c9754a','#8f5a2b','#e0b45a','#4f8f4a'],garnish:'#7fae6a'},
  n:{fr:'Frango à cafreal',en:'Frango à cafreal'},
  p:{fr:'Lisbonne, Portugal',en:'Lisbon, Portugal'},
  d:{fr:"Un poulet ouvert en crapaudine, mariné à la coriandre et au piri-piri, grillé jusqu'à noircir aux bords. Rapporté du Mozambique et de Goa, il est devenu à Lisbonne le plat des churrasqueiras du dimanche soir.",
     en:"A spatchcocked chicken marinated in coriander and piri-piri, grilled until charred at the edges. Brought back from Mozambique and Goa, it became the Sunday-night dish of Lisbon's churrasqueiras."},
  i:[['chicken',1.6,'kg'],['cilantro',2,'bunch'],['garlic',10,'clove'],['piri_piri',6,'pc'],['lemon',3,'pc'],['olive_oil',120,'ml'],['white_wine',100,'ml'],['smoked_paprika',1,'tbsp'],['bay_leaf',2,'pc'],['potato',800,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Ouvrez le poulet en crapaudine en coupant le long de la colonne, et aplatissez-le d'un coup de paume sur le bréchet.","Mixez coriandre, ail, piri-piri, citron, vin blanc et huile d'olive en une marinade verte très parfumée.","Entaillez la chair aux endroits épais et massez la marinade dedans ; laissez 12 heures au frais.","Grillez le poulet côté peau d'abord, à distance des braises, 25 minutes, puis retournez-le pour 15 minutes.","Arrosez de marinade réservée en fin de cuisson. Servez avec des pommes de terre rôties et du citron."],
     en:["Spatchcock the chicken by cutting along the backbone, and flatten it with the heel of your hand on the breastbone.","Blend coriander, garlic, piri-piri, lemon, white wine and olive oil into a fragrant green marinade.","Score the flesh where it is thick and work the marinade in; leave 12 hours in the cold.","Grill the chicken skin side first, away from the coals, for 25 minutes, then turn it for 15 more.","Baste with reserved marinade at the end. Serve with roast potatoes and lemon."]} },

{ id:'bifes-de-cebolada', c:'eu', lat:39.824, lon:-7.492, base:4, prep:20, cook:40, diff:1, tags:['beef','comfort','fast'],
  art:{v:'plate',bg:'#33251c',plate:'#f4ecd8',style:'stew',food:['#8f5a3a','#e0b45a','#c9402c','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Bifes de cebolada',en:'Bifes de cebolada'},
  p:{fr:'Castelo Branco, Beira Baixa, Portugal',en:'Castelo Branco, Beira Baixa, Portugal'},
  d:{fr:"Des tranches de bœuf noyées sous des oignons fondus au vin blanc et au laurier. La cebolada n'est pas une garniture mais la sauce elle-même : il faut trois oignons par personne, et personne ne trouve cela excessif.",
     en:"Slices of beef drowned under onions melted in white wine and bay. The cebolada is not a garnish but the sauce itself: three onions per person, and nobody finds that excessive."},
  i:[['beef_sirloin',700,'g'],['onion',1,'kg'],['garlic',6,'clove'],['white_wine',200,'ml'],['bay_leaf',3,'pc'],['smoked_paprika',1,'tsp'],['olive_oil',100,'ml'],['ripe_tomato',200,'g'],['potato',800,'g'],['frying_oil',600,'ml'],['egg',4,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Aplatissez les tranches de bœuf au maillet et salez-les au dernier moment seulement.","Saisissez-les 90 secondes par face à l'huile brûlante et retirez-les : elles finiront dans la sauce.","Faites fondre les oignons en lamelles dans la même huile, à couvert, 30 minutes, jusqu'à ce qu'ils dorent.","Ajoutez l'ail, le laurier, le paprika, la tomate et le vin blanc, et laissez réduire 10 minutes.","Remettez la viande et son jus pour 5 minutes. Servez avec des frites et un œuf au plat par assiette."],
     en:["Flatten the beef slices with a mallet and salt them only at the last moment.","Sear them 90 seconds a side in scorching oil and lift them out: they will finish in the sauce.","Melt the sliced onions in the same oil, covered, for 30 minutes, until golden.","Add the garlic, bay, paprika, tomato and white wine, and reduce for 10 minutes.","Return the meat and its juices for 5 minutes. Serve with chips and a fried egg on each plate."]} },

{ id:'acorda-de-savel', c:'eu', lat:38.531, lon:-8.891, base:4, prep:30, cook:45, diff:2, tags:['sea','soup','comfort'],
  art:{v:'bowl',bg:'#26384a',plate:'#f4ecd8',style:'soup',food:['#8f6a4a','#c9402c','#e0913a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Açorda de sável',en:'Shad açorda'},
  p:{fr:'Setúbal, Estrémadure, Portugal',en:'Setúbal, Estremadura, Portugal'},
  d:{fr:"Une açorda liée au pain et à l'œuf, avec de l'alose du Sado et beaucoup de coriandre. L'alose est pleine d'arêtes fines : on la poche, on l'effeuille patiemment, et la soupe rachète tout le travail.",
     en:"An açorda thickened with bread and egg, with shad from the Sado and a great deal of coriander. Shad is full of fine bones: you poach it, flake it patiently, and the soup repays the work."},
  i:[['shad',1,'kg'],['rustic_bread',400,'g'],['cilantro',2,'bunch'],['garlic',10,'clove'],['egg',4,'pc'],['olive_oil',120,'ml'],['onion',2,'pc'],['bay_leaf',2,'pc'],['piri_piri',1,'pc'],['lemon',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Pochez l'alose 12 minutes dans une eau salée avec l'oignon et le laurier ; filtrez ce bouillon et gardez-le.","Effeuillez le poisson à la main avec patience, en retirant toutes les arêtes : c'est le seul travail long du plat.","Pilez l'ail dégermé et la coriandre au mortier avec du gros sel et l'huile d'olive.","Émiettez le pain dans un plat creux, versez la pâte verte dessus, puis le bouillon brûlant, et remuez à la fourchette.","Cassez les œufs dans la soupe et remuez 2 minutes hors du feu : ils doivent filer, pas coaguler. Ajoutez le poisson."],
     en:["Poach the shad for 12 minutes in salted water with the onion and bay; strain and keep the broth.","Flake the fish by hand with patience, removing every bone: the only long job in the dish.","Pound the degermed garlic and coriander in a mortar with coarse salt and olive oil.","Crumble the bread into a deep dish, spoon the green paste over it, then the scalding broth, and stir with a fork.","Break the eggs into the soup and stir for 2 minutes off the heat: they should thread, not set. Add the fish."]} },

{ id:'perdiz-a-alcantara', c:'eu', lat:39.290, lon:-7.500, base:4, prep:40, cook:120, diff:3, tags:['festive','slow','poultry'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#6f4a2a','#8f5a3a','#c9754a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Perdrix du couvent d’Alcántara',en:'Alcántara convent partridge'},
  p:{fr:'Portalegre, Alentejo, Portugal',en:'Portalegre, Alentejo, Portugal'},
  d:{fr:"Des perdrix farcies au foie gras et aux truffes, mijotées au porto. La recette fut prise dans un couvent d'Alcántara par un général de Napoléon en 1807 ; sa veuve la publia, et le Portugal ne l'a jamais pardonné.",
     en:"Partridges stuffed with foie gras and truffles, stewed in port. The recipe was seized from a convent at Alcántara by one of Napoleon's generals in 1807; his widow published it, and Portugal has never forgiven it."},
  i:[['partridge',4,'pc'],['foie_gras',200,'g'],['black_truffle',30,'g'],['port_wine',400,'ml'],['duck_fat',80,'g'],['onion',2,'pc'],['carrot',2,'pc'],['bay_leaf',2,'pc'],['thyme',3,'sprig'],['chicken_broth',300,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Videz les perdrix et gardez les foies. Mêlez-les au foie gras et à la truffe hachée, salez et poivrez.","Farcissez les oiseaux de ce mélange et bridez-les serré, pour que la farce ne s'échappe pas.","Faites-les mariner 24 heures dans le porto avec le laurier et le thym, en les retournant deux fois.","Colorez-les à la graisse de canard, ajoutez oignon et carotte, puis la marinade et le fond.","Couvrez et laissez mijoter 1 h 30 à feu très doux. Passez la sauce, faites-la réduire et nappez les oiseaux."],
     en:["Draw the partridges and keep the livers. Mix them with the foie gras and chopped truffle, and season.","Stuff the birds with this and truss them tightly, so the filling cannot escape.","Marinate them for 24 hours in the port with the bay and thyme, turning twice.","Colour them in duck fat, add the onion and carrot, then the marinade and stock.","Cover and simmer for 1½ hours over very low heat. Strain the sauce, reduce it and coat the birds."]} },

{ id:'moelas-guisadas', c:'eu', lat:38.736, lon:-9.142, base:4, prep:20, cook:75, diff:1, tags:['poultry','slow','street'],
  art:{v:'bowl',bg:'#33251c',plate:'#f4ecd8',style:'stew',food:['#8f3b2a','#c9402c','#e0913a','#8f5a3a'],garnish:'#7fae6a'},
  n:{fr:'Moelas guisadas',en:'Moelas guisadas'},
  p:{fr:'Alfama, Lisbonne, Portugal',en:'Alfama, Lisbon, Portugal'},
  d:{fr:"Des gésiers de volaille mijotés au vin blanc, à la tomate et au piri-piri, servis en petriscos dans les tascas. Ils demandent une heure de cuisson pour cesser d'être coriaces : c'est le seul secret.",
     en:"Chicken gizzards stewed in white wine, tomato and piri-piri, served as petiscos in the tascas. They need an hour to stop being tough: that is the only secret."},
  i:[['chicken_gizzards',800,'g'],['onion',3,'pc'],['garlic',8,'clove'],['ripe_tomato',400,'g'],['white_wine',200,'ml'],['bay_leaf',3,'pc'],['piri_piri',2,'pc'],['smoked_paprika',1,'tbsp'],['olive_oil',100,'ml'],['parsley',4,'tbsp'],['rustic_bread',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Parez les gésiers de leur membrane argentée : oubliée, elle reste dure quoi qu'on fasse.","Blanchissez-les 10 minutes et jetez cette eau.","Faites un refogado d'oignon, d'ail et de laurier à l'huile d'olive, 15 minutes, puis ajoutez le paprika hors du feu.","Ajoutez les gésiers, la tomate, le vin blanc et le piri-piri, et couvrez d'eau à hauteur.","Laissez mijoter 1 heure à couvert, puis 15 minutes à découvert pour que la sauce nappe. Servez avec du pain."],
     en:["Trim the silvery membrane from the gizzards: left on, it stays tough whatever you do.","Blanch them for 10 minutes and discard that water.","Make a refogado of onion, garlic and bay in olive oil for 15 minutes, then add the paprika off the heat.","Add the gizzards, tomato, white wine and piri-piri, and cover with water.","Simmer covered for 1 hour, then 15 minutes uncovered so the sauce coats. Serve with bread."]} },

{ id:'arroz-de-forno-minhoto', c:'eu', lat:41.376, lon:-8.573, base:6, prep:25, cook:60, diff:2, tags:['rice','pork','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'rice',food:['#8f6a4a','#c9754a','#e8dcb8','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Arroz de forno minhoto',en:'Minho baked rice'},
  p:{fr:'Vila do Conde, Minho, Portugal',en:'Vila do Conde, Minho, Portugal'},
  d:{fr:"Un riz au four aux viandes fumées et au chorizo, gratiné sur le dessus et moelleux dessous. Le Minho met au four ce que d'autres régions laissent sur le feu : la croûte est la moitié du plaisir.",
     en:"An oven-baked rice with smoked meats and chouriço, crisp on top and yielding below. The Minho bakes what other regions leave on the hob: the crust is half the pleasure."},
  i:[['long_grain_rice',500,'g'],['pork_belly',400,'g'],['chourico',200,'g'],['presunto',150,'g'],['onion',3,'pc'],['garlic',6,'clove'],['smoked_paprika',1,'tbsp'],['white_wine',150,'ml'],['bay_leaf',2,'pc'],['olive_oil',100,'ml'],['parsley',4,'tbsp'],['egg',3,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites cuire le porc 40 minutes avec le laurier ; gardez le bouillon et détaillez la viande en dés.","Faites un refogado d'oignon et d'ail à l'huile, ajoutez le paprika hors du feu, puis le vin blanc.","Ajoutez le riz et laissez-le nacrer, puis mouillez de deux volumes de bouillon pour un de riz.","Ajoutez viandes, chorizo et presunto en dés, et laissez cuire 12 minutes sur le feu : le riz doit rester très humide.","Versez dans un plat de terre, cassez trois œufs dessus et enfournez 20 minutes à 210 °C pour former la croûte."],
     en:["Cook the pork for 40 minutes with the bay; keep the broth and dice the meat.","Make a refogado of onion and garlic in oil, add the paprika off the heat, then the white wine.","Add the rice and let it turn pearly, then add two parts broth to one of rice.","Add the diced meats, chouriço and presunto, and cook for 12 minutes on the hob: the rice must stay very wet.","Turn into an earthenware dish, break three eggs on top and bake for 20 minutes at 210°C to form the crust."]} },

{ id:'bola-de-berlim', c:'eu', lat:37.087, lon:-8.248, base:10, prep:120, cook:20, diff:2, tags:['sweet','street','fry'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#e0b45a','#f2dfa8','#e8c46a','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Bola de Berlim',en:'Bola de Berlim'},
  p:{fr:'Albufeira, Algarve, Portugal',en:'Albufeira, Algarve, Portugal'},
  d:{fr:"Un beignet fourré de crème d'œufs, fendu et non percé, vendu à la criée sur les plages de l'Algarve. Apporté par des réfugiés juifs allemands dans les années 1930, il a pris ici une crème jaune que Berlin ne connaît pas.",
     en:"A doughnut filled with egg cream, split rather than injected, sold by hawkers on Algarve beaches. Brought by German Jewish refugees in the 1930s, it acquired a yellow cream Berlin never knew."},
  i:[['flour',600,'g'],['fresh_yeast',25,'g'],['whole_milk',200,'ml'],['sugar',200,'g'],['egg',4,'pc'],['egg_yolk',6,'pc'],['butter',100,'g'],['lemon_zest',1,'pc'],['cornstarch',40,'g'],['vanilla',1,'pc'],['frying_oil',1.5,'l'],['salt',null,'']],
  s:{fr:["Délayez la levure dans le lait tiède, ajoutez 60 g de sucre, la farine, deux œufs, le beurre et le zeste. Pétrissez 12 minutes.","Laissez lever 1 h 30, puis façonnez des boules de 60 g et laissez-les pousser encore 45 minutes sur un linge fariné.","Pour la crème : portez le lait restant à frémissement, versez-le sur les jaunes battus au sucre et à la fécule, et faites épaissir 3 minutes.","Faites frire les boules à 165 °C, 3 minutes par face : trop chaud, elles brunissent avant d'être cuites à cœur.","Roulez-les dans le sucre tièdes, fendez-les à mi-hauteur sans les traverser, et garnissez généreusement à la poche."],
     en:["Dissolve the yeast in warm milk, add 60 g of sugar, the flour, two eggs, the butter and the zest. Knead for 12 minutes.","Prove for 1½ hours, then shape 60 g balls and let them rise another 45 minutes on a floured cloth.","For the cream: bring the remaining milk to a simmer, pour it over the yolks beaten with sugar and cornstarch, and thicken for 3 minutes.","Fry the balls at 165°C, 3 minutes a side: hotter, and they brown before the centre is cooked.","Roll them in sugar while warm, split them halfway without cutting through, and pipe in the cream generously."]} },

{ id:'tigelada-beira', c:'eu', lat:40.286, lon:-7.503, base:6, prep:15, cook:35, diff:1, tags:['sweet','bake','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ead4',style:'cake',food:['#e8c46a','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Tigelada da Beira',en:'Beira tigelada'},
  p:{fr:'Covilhã, Beira Baixa, Portugal',en:'Covilhã, Beira Baixa, Portugal'},
  d:{fr:"Un flan aux œufs et à la cannelle cuit dans une écuelle de terre, au four à bois. Il n'a ni caramel ni pâte : rien que des œufs, du lait et beaucoup de cannelle, et la croûte brune qui se forme dessus.",
     en:"An egg and cinnamon custard baked in an earthenware bowl in the wood oven. No caramel, no pastry: eggs, milk and a great deal of cinnamon, and the brown crust that forms on top."},
  i:[['egg',8,'pc'],['whole_milk',800,'ml'],['sugar',250,'g'],['flour',30,'g'],['cinnamon',2,'tbsp'],['lemon_zest',1,'pc'],['butter',30,'g'],['salt',null,'']],
  s:{fr:["Portez le lait à frémissement avec le zeste de citron et un bâton de cannelle, puis laissez infuser 20 minutes.","Battez les œufs entiers avec le sucre sans les faire mousser : une tigelada ne doit pas gonfler.","Ajoutez la farine tamisée, puis le lait tiédi en filet, et filtrez l'appareil.","Beurrez des écuelles de terre et remplissez-les aux trois quarts.","Enfournez 30 minutes à 200 °C : le dessus doit brunir franchement et le cœur rester tremblant. Saupoudrez de cannelle."],
     en:["Bring the milk to a simmer with the lemon zest and a cinnamon stick, then infuse off the heat for 20 minutes.","Beat the whole eggs with the sugar without aerating them: a tigelada should not rise.","Add the sifted flour, then the cooled milk in a thin stream, and strain the mixture.","Butter earthenware bowls and fill them three-quarters full.","Bake for 30 minutes at 200°C: the top should brown frankly and the centre stay wobbly. Dust with cinnamon."]} },

{ id:'polvo-guisado-acoreano', c:'eu', lat:38.523, lon:-28.629, base:4, prep:30, cook:60, diff:2, tags:['sea','grill','comfort'],
  art:{v:'board',bg:'#26384a',plate:'#f2ead6',style:'skewer',food:['#8f3b2a','#c9754a','#e0b45a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Polvo guisado des Açores',en:'Azorean stewed octopus'},
  p:{fr:'Horta, Faial, Açores, Portugal',en:'Horta, Faial, Azores, Portugal'},
  d:{fr:"Du poulpe mijoté au vin de Pico, au piment de la terre et à la patate douce. Aux Açores, on le fait cuire avec un bouchon de liège dans la marmite : la coutume est tenace, l'explication moins.",
     en:"Octopus stewed in Pico wine with local chilli and sweet potato. In the Azores a cork goes into the pot with it: the custom is stubborn, the explanation less so."},
  i:[['octopus',1.5,'kg'],['sweet_potato',600,'g'],['onion',3,'pc'],['garlic',8,'clove'],['white_wine',300,'ml'],['ripe_tomato',400,'g'],['bay_leaf',3,'pc'],['piri_piri',2,'pc'],['smoked_paprika',1,'tbsp'],['olive_oil',120,'ml'],['parsley',4,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Congelez le poulpe puis décongelez-le : les fibres se rompent et la chair devient tendre sans effort.","Faites-le raidir à sec dans la marmite jusqu'à ce qu'il rende son eau, et jetez cette première eau.","Ajoutez l'huile, l'oignon en lamelles, l'ail et le laurier, et laissez fondre 20 minutes à couvert.","Versez le vin blanc, la tomate et le piri-piri, et laissez mijoter 40 minutes sans ajouter d'eau.","Ajoutez la patate douce en gros cubes pour les 25 dernières minutes, et couvrez de persil."],
     en:["Freeze the octopus then thaw it: the fibres break and the flesh turns tender without effort.","Stiffen it dry in the pot until it gives up its water, and discard that first water.","Add the oil, sliced onion, garlic and bay, and soften for 20 minutes covered.","Pour in the white wine, tomato and piri-piri, and simmer for 40 minutes without adding water.","Add the sweet potato in large cubes for the last 25 minutes, and cover with parsley."]} },

{ id:'molho-de-figado', c:'eu', lat:37.741, lon:-25.669, base:6, prep:30, cook:90, diff:2, tags:['pork','slow','festive'],
  art:{v:'pot',bg:'#33251c',plate:'#f0e4c8',style:'stew',food:['#8f3b2a','#c9754a','#e0913a','#e8dcb8'],garnish:'#7fae6a'},
  n:{fr:'Molho de fígado',en:'Molho de fígado'},
  p:{fr:'Ponta Delgada, São Miguel, Açores, Portugal',en:'Ponta Delgada, São Miguel, Azores, Portugal'},
  d:{fr:"Du foie de porc mariné au vin et à l'ail, mijoté avec du piment de la terre, servi à Noël. Aux Açores, le molho se prépare le 24 au soir et se mange au petit-déjeuner du 25, avec du pain de maïs.",
     en:"Pig's liver marinated in wine and garlic, stewed with local chilli, served at Christmas. In the Azores the molho is made on the evening of the 24th and eaten for breakfast on the 25th, with maize bread."},
  i:[['pork_liver',1,'kg'],['pork_belly',400,'g'],['red_wine',500,'ml'],['garlic',12,'clove'],['piri_piri',3,'pc'],['bay_leaf',4,'pc'],['allspice',8,'pc'],['smoked_paprika',1,'tbsp'],['lard',60,'g'],['orange',1,'pc'],['corn_bread',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Taillez le foie et la poitrine en cubes et faites-les mariner 24 heures dans le vin, l'ail pilé, le piment et les épices.","Égouttez la viande en gardant la marinade, et épongez-la : mouillée, elle bouillirait au lieu de saisir.","Faites-la colorer par petites quantités dans le saindoux, à feu vif.","Versez la marinade filtrée, ajoutez le zeste d'orange, et laissez mijoter 1 heure à couvert.","Découvrez pour les 20 dernières minutes : la sauce doit napper. Servez avec du pain de maïs."],
     en:["Cut the liver and belly into cubes and marinate them for 24 hours in the wine, pounded garlic, chilli and spices.","Drain the meat keeping the marinade, and pat it dry: wet, it would boil instead of searing.","Colour it in small batches in the lard, over high heat.","Pour in the strained marinade, add the orange zest, and simmer covered for 1 hour.","Uncover for the last 20 minutes: the sauce should coat. Serve with maize bread."]} },

{ id:'sopa-de-castanhas', c:'eu', lat:41.301, lon:-7.744, base:6, prep:25, cook:60, diff:1, tags:['veg','soup','comfort'],
  art:{v:'bowl',bg:'#33291f',plate:'#f4ecd8',style:'soup',food:['#c9a878','#e8dcc0','#8f6a4a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Sopa de castanhas',en:'Chestnut soup'},
  p:{fr:'Vila Real, Trás-os-Montes, Portugal',en:'Vila Real, Trás-os-Montes, Portugal'},
  d:{fr:"Une soupe de châtaignes et de haricots blancs, épaissie sans crème ni farine. Avant la pomme de terre, la châtaigne nourrissait Trás-os-Montes tout l'hiver : on l'appelait le pain des pauvres.",
     en:"A soup of chestnuts and white beans, thickened without cream or flour. Before the potato, chestnuts fed Trás-os-Montes all winter: they were called the bread of the poor."},
  i:[['chestnuts',600,'g'],['white_beans',250,'g'],['onion',2,'pc'],['garlic',6,'clove'],['leek',2,'pc'],['carrot',2,'pc'],['olive_oil',80,'ml'],['bay_leaf',2,'pc'],['presunto',100,'g'],['mint',1,'bunch'],['rustic_bread',1,'pc'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites tremper les haricots une nuit, puis cuisez-les 50 minutes avec le laurier.","Incisez les châtaignes en croix et faites-les bouillir 20 minutes : les deux peaux se retirent alors ensemble, à chaud.","La seconde peau, la fine, doit partir entièrement : oubliée, elle rend la soupe amère.","Faites fondre oignon, poireau et ail à l'huile d'olive, ajoutez les châtaignes et la carotte, et mouillez du bouillon de haricots.","Laissez cuire 30 minutes, mixez la moitié seulement, et servez avec des dés de presunto grillés et de la menthe."],
     en:["Soak the beans overnight, then cook them for 50 minutes with the bay.","Score the chestnuts with a cross and boil them for 20 minutes: both skins then come away together, while hot.","The second, thin skin must come off completely: left on, it makes the soup bitter.","Soften the onion, leek and garlic in olive oil, add the chestnuts and carrot, and moisten with the bean broth.","Cook for 30 minutes, blend only half of it, and serve with crisped presunto dice and mint."]} },

{ id:'bolas-de-berlim-natario', c:'eu', lat:41.6936, lon:-8.8302, base:10, prep:150, cook:20, diff:3, tags:['sweet','street','fry'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#f2dfa8','#c9924a','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Bolas de Berlim de chez Natário',en:'Natário bolas de Berlim'},
  p:{fr:'Viana do Castelo, Minho, Portugal',en:'Viana do Castelo, Minho, Portugal'},
  d:{fr:"La maison Manuel Natário, ouverte vers 1935 près du musée du Costume, en vend plus de mille par jour et la file d'attente déborde sur le trottoir. Contrairement à celle des plages de l'Algarve, qu'on fend, celle-ci est injectée à la poche après avoir été roulée dans le sucre à la cannelle — et elle se mange tiède, à la sortie de la friture.",
     en:"Manuel Natário's shop, opened around 1935 near the costume museum, sells more than a thousand a day and the queue spills onto the pavement. Unlike the Algarve beach version, which is split open, this one is piped through the side after being rolled in cinnamon sugar — and it is eaten warm, straight from the fryer."},
  i:[['flour',600,'g'],['fresh_yeast',30,'g'],['whole_milk',450,'ml'],['sugar',250,'g'],['egg',3,'pc'],['egg_yolk',8,'pc'],['butter',120,'g'],['lemon_zest',1,'pc'],['cornstarch',45,'g'],['vanilla',1,'pc'],['cinnamon',2,'tsp'],['frying_oil',1.5,'l'],['salt',null,'']],
  s:{fr:["Délayez la levure dans 150 ml de lait tiède avec une cuillerée de sucre, et attendez qu'elle mousse.","Pétrissez-la 15 minutes avec la farine, les œufs entiers, deux jaunes, 80 g de sucre, le beurre, le zeste et le sel : la pâte doit se décoller du bol et rester souple.","Laissez lever 1 h 30, façonnez des boules de 55 g, aplatissez-les à peine et laissez-les pousser 1 heure sur un linge fariné — c'est cette seconde pousse qui donne la ceinture claire au milieu.","Pendant ce temps, faites une crème avec le lait restant, les six jaunes, 100 g de sucre, la fécule et la vanille ; couvrez-la au contact et laissez-la refroidir complètement avant de la lisser au fouet.","Faites-les frire à 165 °C, 3 minutes par face, roulez-les aussitôt dans le sucre à la cannelle, puis garnissez-les à la poche par un trou percé sur le côté. Elles ne se gardent pas : c'est le prix de la file d'attente."],
     en:["Dissolve the yeast in 150 ml of warm milk with a spoonful of sugar, and wait for it to foam.","Knead it for 15 minutes with the flour, whole eggs, two yolks, 80 g of sugar, the butter, zest and salt: the dough should leave the bowl and stay supple.","Prove for 1½ hours, shape 55 g balls, flatten them barely and let them rise for an hour on a floured cloth — that second rise is what gives the pale belt around the middle.","Meanwhile make a custard with the remaining milk, six yolks, 100 g of sugar, the cornstarch and the vanilla; cover it in contact and let it cool completely before whisking it smooth.","Fry at 165°C, 3 minutes a side, roll them straight away in the cinnamon sugar, then pipe in the cream through a hole made in the side. They do not keep: that is the price of the queue."]} },

{ id:'poulet-de-mamie', c:'eu', lat:41.714, lon:-8.858, base:4, prep:20, cook:75, diff:1, tags:['poultry','comfort','slow'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#c9532c','#e0b45a','#8f5a3a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Poulet de Mamie',en:"Grandmother's chicken"},
  p:{fr:'Areosa, Viana do Castelo, Portugal',en:'Areosa, Viana do Castelo, Portugal'},
  d:{fr:"Un poulet mijoté au vin blanc et au colorau, la paprika douce que le Minho verse à la cuillère à soupe et non à la pincée. Recette de famille de l'Areosa, où l'on retire la peau et où l'on ne lésine jamais sur l'huile d'olive : c'est elle qui porte la couleur du piment.",
     en:"A chicken stewed in white wine and colorau, the sweet paprika the Minho measures by the tablespoon rather than the pinch. A family recipe from Areosa, where the skin comes off and the olive oil is never stinted: it is the oil that carries the colour of the pepper."},
  i:[['chicken',1.5,'kg'],['onion',2,'pc'],['lardons',200,'g'],['olive_oil',120,'ml'],['white_wine',300,'ml'],['sweet_paprika',4,'tbsp'],['cayenne',1,'tsp'],['peas',300,'g'],['long_grain_rice',300,'g'],['salt',null,'']],
  s:{fr:["Découpez le poulet en morceaux et retirez la peau : sans elle, la sauce reste franche et prend la couleur du piment au lieu du gras.","Faites suer les oignons émincés et les lardons dans l'huile d'olive, généreusement — au moins un bon verre.","Ajoutez les morceaux de poulet et faites-les revenir 5 minutes, sans chercher à les colorer fortement.","Versez deux verres de vin blanc, le paprika doux, le piment de Cayenne et le sel, puis de l'eau à hauteur. Laissez mijoter 1 heure à couvert, à petit feu.","Ajoutez les petits pois un quart d'heure avant la fin. Servez avec du riz blanc, ou du riz au four si le repas est un dimanche."],
     en:["Joint the chicken and take off the skin: without it the sauce stays clean and takes the colour of the pepper rather than of fat.","Sweat the sliced onions and the lardons in olive oil, generously — a good glassful at least.","Add the chicken pieces and turn them for 5 minutes, without trying to brown them hard.","Pour in two glasses of white wine, the sweet paprika, the cayenne and salt, then water to cover. Simmer covered for 1 hour over low heat.","Add the peas a quarter of an hour before the end. Serve with plain rice, or oven-baked rice if the meal is a Sunday one."]} },

{ id:'pataniscas-de-bacalhau', c:'eu', lat:38.712, lon:-9.139, base:4, prep:30, cook:20, diff:1, tags:['sea','fry','comfort'],
  art:{v:'plate',bg:'#33301f',plate:'#f4ecd8',style:'flat',food:['#e0b45a','#c9924a','#f2dfa8','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Pataniscas de bacalhau',en:'Salt cod pataniscas'},
  p:{fr:'Lisbonne, Portugal',en:'Lisbon, Portugal'},
  d:{fr:"Des beignets plats de morue effilochée, servis avec un riz de haricots noir de coriandre. C'est le déjeuner des tascas lisboètes : la patanisca doit être irrégulière et dentelée sur les bords, une galette parfaitement ronde trahit trop de farine.",
     en:"Flat fritters of shredded salt cod, served with a bean rice black with coriander. This is the lunch of Lisbon tascas: a patanisca must be irregular and ragged at the edges, a perfectly round one betrays too much flour."},
  i:[['salt_cod',500,'g'],['flour',150,'g'],['egg',3,'pc'],['onion',1,'pc'],['garlic',2,'clove'],['parsley',5,'tbsp'],['whole_milk',100,'ml'],['frying_oil',600,'ml'],['long_grain_rice',250,'g'],['black_beans',200,'g'],['cilantro',1,'bunch'],['olive_oil',60,'ml'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Dessalez la morue 24 heures en changeant l'eau quatre fois, puis pochez-la 8 minutes et effilochez-la à la main, en gros filaments.","Ne la hachez surtout pas : la patanisca doit garder des fibres reconnaissables sous la dent.","Battez les œufs avec la farine et le lait, ajoutez l'oignon râpé, l'ail et beaucoup de persil, et laissez reposer 30 minutes.","Incorporez la morue : l'appareil doit tenir à la cuillère mais rester lâche, sinon ajoutez du lait.","Déposez des cuillerées dans l'huile à 175 °C sans les étaler et retournez à mi-cuisson. Servez avec un arroz de feijão à la coriandre."],
     en:["Desalt the cod for 24 hours, changing the water four times, then poach it for 8 minutes and shred it by hand into coarse strands.","On no account chop it: a patanisca must keep fibres you can recognise between the teeth.","Beat the eggs with the flour and milk, add grated onion, garlic and plenty of parsley, and rest for 30 minutes.","Fold in the cod: the batter should hold on the spoon but stay loose, otherwise add milk.","Drop spoonfuls into oil at 175°C without spreading them and turn halfway. Serve with a coriander bean rice."]} },

{ id:'prego-no-pao', c:'eu', lat:38.7115, lon:-9.1400, base:4, prep:20, cook:10, diff:1, tags:['beef','fast','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'roll',food:['#8f3b2a','#e0b45a','#f0e8d0','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Prego no pão',en:'Prego no pão'},
  p:{fr:'Lisbonne, Portugal',en:'Lisbon, Portugal'},
  d:{fr:"Un steak à l'ail dans un petit pain, mangé debout au comptoir ou en fin de repas, après le poisson. Prego veut dire clou : on clouait autrefois des gousses d'ail dans la viande pour l'attendrir, et le nom est resté quand la pratique a disparu.",
     en:"A garlic steak in a soft roll, eaten standing at the counter or at the end of a meal, after the fish. Prego means nail: garlic cloves were once nailed into the meat to tenderise it, and the name outlived the practice."},
  i:[['beef_steak',4,'pc'],['garlic',8,'clove'],['bay_leaf',3,'pc'],['white_wine',100,'ml'],['butter',60,'g'],['bread_roll',4,'pc'],['mustard',2,'tbsp'],['piri_piri',1,'tsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Aplatissez les steaks au plat de la main, pas au maillet : il s'agit de les élargir, non d'en briser les fibres.","Pilez l'ail avec le sel et le laurier émietté, et frottez-en la viande des deux côtés ; laissez reposer 20 minutes.","Chauffez la poêle à blanc, huilez-la à peine, et saisissez 90 secondes par face : au-delà, un steak fin devient une semelle.","Déglacez au vin blanc avec une noix de beurre et raclez les sucs — cette sauce d'une cuillerée est tout ce qui distingue un bon prego.","Fendez le pain, versez le jus à l'intérieur pour qu'il l'absorbe, posez le steak, un peu de moutarde et de piri-piri. Se mange aussitôt."],
     en:["Flatten the steaks with the palm, not a mallet: the aim is to widen them, not to break the fibres.","Pound the garlic with salt and crumbled bay, and rub it into both sides; rest for 20 minutes.","Heat the pan white hot, barely oil it, and sear 90 seconds a side: any longer and a thin steak turns to shoe leather.","Deglaze with white wine and a knob of butter and scrape up the sediment — that spoonful of sauce is all that separates a good prego from a bad one.","Split the roll, pour the juices inside so the bread drinks them, add the steak, a little mustard and piri-piri. Eaten at once."]} },

{ id:'bife-a-marrare', c:'eu', lat:38.7095, lon:-9.1425, base:4, prep:15, cook:12, diff:2, tags:['beef','fast','comfort'],
  art:{v:'plate',bg:'#2b2419',plate:'#f4f0e6',style:'grill',food:['#8f3b2a','#f4f0e6','#e0b45a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Bife à Marrare',en:'Bife à Marrare'},
  p:{fr:'Chiado, Lisbonne, Portugal',en:'Chiado, Lisbon, Portugal'},
  d:{fr:"Le steak à la crème et au poivre du café Marrare, où se réunissait le Lisbonne littéraire du XIXᵉ siècle. Un unique poêlon servait toute la soirée sans être lavé : les sucs s'accumulaient, et la sauce du dernier client valait mieux que celle du premier.",
     en:"The cream-and-pepper steak of the Marrare café, where literary Lisbon gathered in the 19th century. A single pan served the whole evening unwashed: the sediment built up, and the last customer's sauce was better than the first's."},
  i:[['sirloin_steak',4,'pc'],['heavy_cream',250,'ml'],['garlic',4,'clove'],['butter',60,'g'],['white_wine',100,'ml'],['bay_leaf',2,'pc'],['black_peppercorns',2,'tbsp'],['potato',800,'g'],['frying_oil',1,'l'],['salt',null,'']],
  s:{fr:["Sortez la viande une heure à l'avance et épongez-la : un steak humide bout au lieu de saisir.","Concassez le poivre au mortier plutôt que de le moudre, et pressez-le sur les deux faces.","Saisissez au beurre mousseux avec l'ail écrasé en chemise et le laurier, 2 minutes par face pour un centimètre et demi.","Réservez la viande, déglacez au vin, laissez réduire presque à sec, puis versez la crème et laissez-la épaissir sans bouillir.","Remettez les steaks une minute dans la sauce pour qu'ils la nappent. Servez avec des frites fines et rien d'autre."],
     en:["Take the meat out an hour ahead and pat it dry: a wet steak boils instead of searing.","Crack the pepper in a mortar rather than grinding it, and press it onto both faces.","Sear in foaming butter with crushed unpeeled garlic and bay, 2 minutes a side for a centimetre and a half.","Set the meat aside, deglaze with wine, reduce almost dry, then pour in the cream and let it thicken without boiling.","Return the steaks for a minute so the sauce coats them. Serve with thin chips and nothing else."]} },

{ id:'ovos-moles-de-aveiro', c:'eu', lat:40.641, lon:-8.653, base:24, prep:60, cook:20, diff:3, tags:['sweet','festive','bake'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e8c46a','#f4f0e6','#f2dfa8','#f0e8d0'],garnish:'#c9754a'},
  n:{fr:'Ovos moles d’Aveiro',en:'Ovos moles of Aveiro'},
  p:{fr:'Aveiro, Beira Litoral, Portugal',en:'Aveiro, Beira Litoral, Portugal'},
  d:{fr:"Une crème de jaunes d'œufs et de sucre enfermée dans des coques d'hostie moulées en coquillages et en barriques de sel. Les couvents d'Aveiro les préparaient depuis le XVIᵉ siècle avec les jaunes que leur laissait l'amidonnage des voiles et du linge.",
     en:"A cream of egg yolks and sugar enclosed in wafer shells moulded as seashells and salt barrels. The convents of Aveiro made them from the 16th century with the yolks left over from starching sails and linen."},
  i:[['egg_yolk',12,'pc'],['sugar',250,'g'],['water',125,'ml'],['rice_paper',10,'sheet'],['lemon_zest',1,'pc'],['salt',null,'']],
  s:{fr:["Portez le sucre et l'eau à 108 °C — au petit boulé — et laissez refroidir jusqu'à 40 °C avec le zeste.","Passez les jaunes au tamis fin pour ôter les chalazes : ce sont elles qui forment les grumeaux blancs qu'on ne rattrape plus.","Versez le sirop tiède sur les jaunes en filet, en fouettant, puis remettez sur feu très doux.","Remuez sans arrêt à la spatule, en raclant le fond, jusqu'à ce que la crème se détache en une masse — 12 minutes environ. Une seconde d'inattention et les œufs grènent.","Laissez refroidir 12 heures, puis garnissez les coques d'hostie, soudez-les à l'eau et parez au ciseau."],
     en:["Bring the sugar and water to 108°C — soft ball — and let it cool to 40°C with the zest.","Push the yolks through a fine sieve to remove the chalazae: they are what form the white specks nothing can undo.","Pour the warm syrup onto the yolks in a stream, whisking, then return to very low heat.","Stir constantly with a spatula, scraping the base, until the cream pulls away in one mass — about 12 minutes. A second's inattention and the eggs scramble.","Cool for 12 hours, then fill the wafer shells, seal them with water and trim with scissors."]} },

{ id:'sopa-de-cacao', c:'eu', lat:38.372, lon:-8.513, base:4, prep:25, cook:30, diff:2, tags:['sea','soup','comfort'],
  art:{v:'bowl',bg:'#28331f',plate:'#f4ecd8',style:'soup',food:['#7fae5a','#e8dcb8','#f0e8d0','#4f6f3a'],garnish:'#6fbf8f'},
  n:{fr:'Sopa de cação',en:'Dogfish soup'},
  p:{fr:'Alcácer do Sal, Alentejo, Portugal',en:'Alcácer do Sal, Alentejo, Portugal'},
  d:{fr:"Une soupe d'aiguillat liée à la farine, verte de coriandre et acidulée au vinaigre, versée sur du pain rassis. L'Alentejo est une terre sans mer : le cação, poisson de peu de prix et sans arêtes fines, montait salé depuis Setúbal.",
     en:"A dogfish soup thickened with flour, green with coriander and sharpened with vinegar, poured over stale bread. The Alentejo is a land without a coast: dogfish, cheap and free of small bones, came up salted from Setúbal."},
  i:[['dogfish',800,'g'],['cilantro',2,'bunch'],['garlic',8,'clove'],['flour',40,'g'],['olive_oil',100,'ml'],['white_vinegar',60,'ml'],['bay_leaf',2,'pc'],['onion',1,'pc'],['bread',300,'g'],['salt',null,'']],
  s:{fr:["Faites tremper le poisson une heure s'il est salé, puis pochez-le 10 minutes dans l'eau avec l'oignon et le laurier ; gardez le bouillon.","Effeuillez la chair en gros morceaux et retirez le cartilage central, qui se détache d'un seul tenant.","Pilez au mortier l'ail, la coriandre et le sel : c'est la base du plat, et le mortier libère l'huile de la coriandre comme aucun couteau.","Faites blondir la farine dans l'huile d'olive, mouillez du bouillon de cuisson et laissez épaissir 10 minutes.","Ajoutez le pilon, le vinaigre et le poisson, chauffez sans bouillir, et versez sur des tranches de pain rassis au fond des assiettes."],
     en:["Soak the fish for an hour if salted, then poach it for 10 minutes with the onion and bay; keep the broth.","Flake the flesh in large pieces and remove the central cartilage, which comes away in one piece.","Pound the garlic, coriander and salt in a mortar: this is the base of the dish, and a mortar releases coriander oil as no knife does.","Turn the flour golden in olive oil, moisten with the cooking broth and let it thicken for 10 minutes.","Add the pounded paste, the vinegar and the fish, heat without boiling, and pour over slices of stale bread in the plates."]} },

{ id:'dom-rodrigo', c:'eu', lat:37.102, lon:-8.674, base:12, prep:70, cook:25, diff:3, tags:['sweet','festive','fruit'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e8c46a','#f2dfa8','#c9924a','#f4f0e6'],garnish:'#c9754a'},
  n:{fr:'Dom Rodrigo',en:'Dom Rodrigo'},
  p:{fr:'Lagos, Algarve, Portugal',en:'Lagos, Algarve, Portugal'},
  d:{fr:"Des fils d'œufs et une crème d'amandes à la cannelle, torsadés dans un papier d'aluminium coloré comme un bonbon. Le nom viendrait de dom Rodrigo Lobo da Silveira, gouverneur de Lagos ; l'emballage, lui, est venu bien plus tard, quand la friandise a pris la route des marchés.",
     en:"Egg threads and a cinnamon almond cream, twisted in coloured foil like a sweet. The name is said to come from Dom Rodrigo Lobo da Silveira, governor of Lagos; the wrapper came much later, when the sweet took to the markets."},
  i:[['egg_yolk',14,'pc'],['sugar',400,'g'],['water',250,'ml'],['ground_almonds',150,'g'],['cinnamon',2,'tsp'],['lemon_zest',1,'pc'],['egg',2,'pc']],
  s:{fr:["Préparez un sirop à 105 °C avec 300 g de sucre, l'eau et le zeste, et maintenez-le frémissant.","Pour les fios de ovos, passez huit jaunes au tamis, versez-les en filet fin dans le sirop à travers un entonnoir, en tournant : ils prennent en fils dorés en 20 secondes.","Retirez-les à l'écumoire dès qu'ils flottent — une seconde de trop et les fils deviennent cassants.","Faites une crème d'amandes avec le reste du sucre, les amandes en poudre, six jaunes et la cannelle, cuite à feu doux jusqu'à ce qu'elle se détache.","Déposez une cuillerée de crème sur un carré de papier, couronnez de fils d'œufs et torsadez les extrémités. Se conserve deux semaines."],
     en:["Make a syrup at 105°C with 300 g of the sugar, the water and the zest, and keep it at a tremble.","For the fios de ovos, sieve eight yolks and pour them in a fine stream into the syrup through a funnel, moving in circles: they set into golden threads in 20 seconds.","Lift them out with a skimmer the moment they float — a second too long and the threads turn brittle.","Make an almond cream with the remaining sugar, the ground almonds, six yolks and the cinnamon, cooked gently until it pulls away.","Set a spoonful of cream on a square of foil, crown it with egg threads and twist the ends. Keeps for two weeks."]} },

{ id:'conquilhas-a-algarvia', c:'eu', lat:37.023, lon:-7.938, base:4, prep:60, cook:5, diff:1, tags:['sea','fast','fresh'],
  art:{v:'bowl',bg:'#26485c',plate:'#f4f0e6',style:'other',food:['#e8dcc0','#f4f0e6','#7fae5a','#e0b45a'],garnish:'#6fbf8f'},
  n:{fr:'Conquilhas à l’algarvia',en:'Algarve wedge clams'},
  p:{fr:'Faro, Algarve, Portugal',en:'Faro, Algarve, Portugal'},
  d:{fr:"Des tellines ramassées à marée basse dans le sable de la ria Formosa, ouvertes en deux minutes à l'ail et à la coriandre. Rien ne se rate plus vite : une telline cuite trente secondes de trop se rétracte en gomme et ne se rattrape pas.",
     en:"Wedge clams gathered at low tide from the sand of the Ria Formosa, opened in two minutes with garlic and coriander. Nothing is ruined faster: thirty seconds too long and a wedge clam shrinks to rubber, past saving."},
  i:[['wedge_clams',1,'kg'],['garlic',5,'clove'],['cilantro',1,'bunch'],['olive_oil',60,'ml'],['lemon',1,'pc'],['white_wine',80,'ml'],['bread',300,'g'],['salt',null,'']],
  s:{fr:["Faites dégorger les tellines 2 heures dans une eau salée à 35 g par litre, en changeant l'eau deux fois : elles doivent rendre tout leur sable.","Écartez celles qui restent ouvertes, puis rincez-les à grande eau froide et égouttez-les.","Faites blondir l'ail émincé dans l'huile d'olive sans le brûler — brûlé, il rend la sauce amère et rien ne la rattrape.","Jetez les tellines à feu vif avec le vin blanc, couvrez et secouez la poêle : elles s'ouvrent en 90 secondes.","Coupez le feu dès la dernière ouverte, ajoutez la coriandre hachée et le jus de citron. Servez à la poêle, avec du pain pour le jus."],
     en:["Purge the clams for 2 hours in water salted to 35 g per litre, changing it twice: they must give up all their sand.","Discard any that stay open, then rinse them under plenty of cold water and drain.","Turn the sliced garlic pale gold in olive oil without burning it — burnt, it makes the sauce bitter and nothing saves it.","Tip in the clams over high heat with the white wine, cover and shake the pan: they open in 90 seconds.","Kill the heat the moment the last one opens, add chopped coriander and lemon juice. Serve in the pan, with bread for the juices."]} },

{ id:'espada-com-banana', c:'eu', lat:32.650, lon:-16.908, base:4, prep:25, cook:15, diff:2, tags:['sea','fry','fruit'],
  art:{v:'plate',bg:'#26384a',plate:'#f4ecd8',style:'fish',food:['#f0e8d0','#e8c46a','#f2dfa8','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Espada com banana',en:'Scabbardfish with banana'},
  p:{fr:'Funchal, Madère, Portugal',en:'Funchal, Madeira, Portugal'},
  d:{fr:"Des filets de poisson-sabre noir panés, servis avec de la banane madérienne poêlée et du fruit de la passion. L'espada se pêche à mille mètres de fond, la nuit, à la palangre : ses yeux énormes et sa peau d'argent ne survivent pas à la remontée.",
     en:"Breaded fillets of black scabbardfish, served with pan-fried Madeiran banana and passion fruit. The espada is caught a thousand metres down, at night, on longlines: its huge eyes and silver skin do not survive the ascent."},
  i:[['scabbard_fish',800,'g'],['banana',4,'pc'],['flour',80,'g'],['egg',2,'pc'],['butter',60,'g'],['passion_fruit',4,'pc'],['lemon',2,'pc'],['garlic',3,'clove'],['olive_oil',60,'ml'],['potato',600,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Faites mariner les filets 20 minutes au jus de citron, à l'ail pilé et au sel : la chair est douce et manque d'acidité.","Épongez-les à fond, farinez-les puis passez-les à l'œuf battu — dans cet ordre, sinon la farine glisse.","Poêlez à l'huile 2 minutes par face : le filet est fin, il cuit avant qu'on ait fini de le retourner.","Coupez les bananes en deux dans la longueur et faites-les caraméliser au beurre, sans les remuer, jusqu'à ce qu'elles dorent.","Dressez le poisson, la banane par-dessus, et arrosez de pulpe de fruit de la passion. L'acidité fait le lien entre le sucré et le poisson."],
     en:["Marinate the fillets for 20 minutes in lemon juice, crushed garlic and salt: the flesh is mild and short of acidity.","Pat them thoroughly dry, flour them then dip in beaten egg — in that order, or the flour slides off.","Fry in oil 2 minutes a side: the fillet is thin, and cooks before you have finished turning it.","Halve the bananas lengthwise and caramelise them in butter, without stirring, until golden.","Plate the fish, banana on top, and spoon over passion fruit pulp. The acidity is what links the sweetness to the fish."]} },

{ id:'picado-madeirense', c:'eu', lat:32.648, lon:-16.914, base:4, prep:20, cook:20, diff:1, tags:['beef','street','fast'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'stew',food:['#8f5a3a','#e0b45a','#c9924a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Picado madérien',en:'Madeiran picado'},
  p:{fr:'Funchal, Madère, Portugal',en:'Funchal, Madeira, Portugal'},
  d:{fr:"Des dés de bœuf à l'ail et au vin de Madère, jetés sur un lit de frites, posés au milieu de la table avec autant de fourchettes que de convives. Il n'y a pas d'assiettes : on pique — picar — directement dans le plat, et c'est de là que vient le nom.",
     en:"Cubes of beef with garlic and Madeira wine, tipped over a bed of chips, set in the middle of the table with as many forks as there are people. There are no plates: you pick — picar — straight from the dish, and that is where the name comes from."},
  i:[['beef_sirloin',700,'g'],['garlic',8,'clove'],['madeira_wine',120,'ml'],['bay_leaf',3,'pc'],['butter',60,'g'],['piri_piri',1,'tsp'],['potato',1,'kg'],['frying_oil',1,'l'],['red_pepper',1,'pc'],['parsley',3,'tbsp'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Taillez le bœuf en dés de 2 cm et faites-les mariner 1 heure avec l'ail pilé, le laurier, le sel et le piri-piri.","Coupez les pommes de terre en frites épaisses et faites-les frire en deux bains : blanchies à 150 °C, dorées à 180 °C.","Épongez la viande et saisissez-la au beurre à feu très vif, par petites quantités : entassée, elle rendrait son eau et bouillirait.","Déglacez au vin de Madère, laissez réduire de moitié et remettez la viande une minute.","Versez la viande et son jus sur les frites brûlantes, parsemez de persil et de poivron, et posez le plat au centre de la table."],
     en:["Cut the beef into 2 cm dice and marinate for an hour with crushed garlic, bay, salt and piri-piri.","Cut the potatoes into thick chips and fry them twice: blanched at 150°C, browned at 180°C.","Pat the meat dry and sear it in butter over fierce heat, in small batches: crowded, it would weep and boil.","Deglaze with Madeira, reduce by half and return the meat for a minute.","Tip the meat and its juices over the scalding chips, scatter parsley and pepper, and set the dish in the middle of the table."]} },

{ id:'milho-frito', c:'eu', lat:32.650, lon:-16.977, base:6, prep:30, cook:40, diff:2, tags:['veg','fry','comfort'],
  art:{v:'plate',bg:'#33301f',plate:'#f4ecd8',style:'flat',food:['#e8c46a','#e0b45a','#4f6f3a','#f2dfa8'],garnish:'#7fae6a'},
  n:{fr:'Milho frito',en:'Milho frito'},
  p:{fr:'Câmara de Lobos, Madère, Portugal',en:'Câmara de Lobos, Madeira, Portugal'},
  d:{fr:"Des cubes de polenta au chou et au fenouil sauvage, refroidis une nuit puis frits jusqu'à ce qu'ils craquent. L'accompagnement obligé de l'espetada madérienne : le cœur doit rester crémeux sous une croûte qui résiste, ce que seul un refroidissement complet permet.",
     en:"Cubes of cornmeal with cabbage and wild fennel, chilled overnight then fried until they crack. The obligatory partner to Madeiran espetada: the centre must stay creamy under a crust that resists, which only a full chilling allows."},
  i:[['cornmeal',300,'g'],['collard_greens',300,'g'],['fennel',1,'bunch'],['garlic',4,'clove'],['lard',80,'g'],['water',1.2,'l'],['frying_oil',600,'ml'],['salt',null,'']],
  s:{fr:["Faites bouillir l'eau salée avec le chou émincé finement, l'ail et le fenouil sauvage haché, 15 minutes.","Versez la farine de maïs en pluie en fouettant sans arrêt, pour éviter le moindre grumeau.","Remuez 25 minutes à la cuillère de bois, à feu doux : c'est long, et c'est ce qui empêche la bouillie d'avoir un goût de cru.","Ajoutez le saindoux, versez dans un plat sur 3 cm d'épaisseur, lissez et laissez refroidir une nuit au réfrigérateur.","Découpez des cubes de 4 cm et faites-les frire à 180 °C jusqu'à ce qu'ils soient dorés de tous côtés. Un cube tiède se défait dans l'huile."],
     en:["Boil the salted water with the finely shredded cabbage, garlic and chopped wild fennel for 15 minutes.","Rain in the cornmeal, whisking constantly, to avoid the smallest lump.","Stir for 25 minutes with a wooden spoon over low heat: it is long, and it is what stops the porridge tasting raw.","Add the lard, pour into a dish 3 cm deep, smooth the top and chill overnight.","Cut 4 cm cubes and fry at 180°C until golden on every side. A warm cube falls apart in the oil."]} },

{ id:'lapas-grelhadas', c:'eu', lat:38.535, lon:-28.626, base:4, prep:15, cook:8, diff:1, tags:['sea','grill','fast'],
  art:{v:'plate',bg:'#26485c',plate:'#f4ecd8',style:'other',food:['#e8dcc0','#c9924a','#f0e8d0','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Lapas grelhadas',en:'Grilled limpets'},
  p:{fr:'Horta, Faial, Açores, Portugal',en:'Horta, Faial, Azores, Portugal'},
  d:{fr:"Des patelles arrachées aux rochers noirs, grillées dans leur coquille sous un beurre d'ail et arrosées de citron. Elles se ramassent au couteau et d'un seul geste : hésiter une seconde, et la patelle se colle à la pierre avec une force qu'on ne vainc plus.",
     en:"Limpets prised off the black rocks, grilled in their shells under garlic butter and doused with lemon. They are lifted with a knife in a single movement: hesitate a second and the limpet clamps to the stone with a force nothing overcomes."},
  i:[['limpets',1,'kg'],['butter',150,'g'],['garlic',6,'clove'],['lemon',3,'pc'],['piri_piri',1,'tsp'],['parsley',3,'tbsp'],['bread',300,'g'],['salt',null,'']],
  s:{fr:["Brossez les coquilles sous l'eau froide et laissez les patelles dégorger 30 minutes en eau de mer ou en eau très salée.","Travaillez le beurre en pommade avec l'ail pilé, le persil et le piri-piri.","Rangez les lapas côté chair vers le haut sur une plaque brûlante ou directement sur les braises.","Déposez une noisette de beurre sur chacune dès qu'elles commencent à grésiller, et comptez 4 minutes en tout — cuites davantage, elles durcissent et se décollent mal.","Arrosez de citron à la sortie et servez avec du pain de maïs pour le beurre resté dans les coquilles."],
     en:["Scrub the shells under cold water and let the limpets purge for 30 minutes in seawater or heavily salted water.","Cream the butter with the crushed garlic, parsley and piri-piri.","Set the limpets flesh upward on a scalding plate or straight on the coals.","Drop a hazelnut of butter on each as soon as they start to sizzle, and give them 4 minutes in all — cooked longer they toughen and cling.","Squeeze lemon over as they come off and serve with corn bread for the butter left in the shells."]} },

{ id:'cracas-cozidas', c:'eu', lat:38.733, lon:-27.067, base:4, prep:15, cook:10, diff:2, tags:['sea','fast','fresh'],
  art:{v:'bowl',bg:'#26384a',plate:'#f4ecd8',style:'other',food:['#8f8f7a','#e8dcc0','#f0e8d0','#7fae5a'],garnish:'#6fbf8f'},
  n:{fr:'Cracas',en:'Cracas'},
  p:{fr:'Praia da Vitória, Terceira, Açores, Portugal',en:'Praia da Vitória, Terceira, Azores, Portugal'},
  d:{fr:"Des balanes géantes détachées au burin des rochers volcaniques, cuites à l'eau de mer et mangées à l'aide d'une épingle. Elles ne poussent que sur la lave battue par la houle atlantique et se vendent à la plaque entière, comme un morceau de récif.",
     en:"Giant barnacles chiselled off the volcanic rock, boiled in seawater and eaten with a pin. They grow only on lava beaten by the Atlantic swell and are sold as whole plates, like a piece of reef."},
  i:[['barnacles',1.5,'kg'],['coarse_salt',3,'tbsp'],['bay_leaf',2,'pc'],['lemon',2,'pc'],['butter',60,'g'],['piri_piri',1,'tsp'],['bread',200,'g']],
  s:{fr:["Rincez les plaques à grande eau froide en frottant la roche pour ôter le sable et les algues.","Portez à ébullition une eau très salée — 40 g par litre, l'eau de mer si vous l'avez — avec le laurier.","Plongez les cracas et comptez 6 minutes à partir de la reprise de l'ébullition, pas davantage : trop cuites, elles se contractent au fond de leur cône et deviennent impossibles à sortir.","Égouttez et servez brûlantes, avec une épingle ou une fourchette à escargot par convive.","Un beurre fondu au piri-piri et un quartier de citron suffisent. La chair est déjà salée : ne resalez pas."],
     en:["Rinse the plates under plenty of cold water, scrubbing the rock to remove sand and weed.","Bring heavily salted water to the boil — 40 g per litre, or seawater if you have it — with the bay.","Drop in the barnacles and count 6 minutes from the return to the boil, no longer: overcooked, they retract to the bottom of their cone and become impossible to extract.","Drain and serve scalding, with a pin or a snail fork per person.","Melted butter with piri-piri and a wedge of lemon are enough. The flesh is already salty: do not salt again."]} },

{ id:'pastel-de-chaves', c:'eu', lat:41.7435, lon:-7.4715, base:8, prep:90, cook:25, diff:3, tags:['beef','bake','street'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e0b45a','#f2dfa8','#8f5a3a','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Pastel de Chaves',en:'Pastel de Chaves'},
  p:{fr:'Chaves, Trás-os-Montes, Portugal',en:'Chaves, Trás-os-Montes, Portugal'},
  d:{fr:"Un chausson de pâte feuilletée en forme de demi-lune, fourré de veau et de porc hachés crus, protégé par une indication géographique depuis 2011. La recette originale, apparue vers 1862, se transmet oralement : la farce entre crue et cuit dans son propre jus enfermé par le feuilletage.",
     en:"A puff-pastry half-moon filled with raw minced veal and pork, protected by a geographical indication since 2011. The original recipe, appearing around 1862, is passed on by word of mouth: the filling goes in raw and cooks in its own juices, sealed by the pastry."},
  i:[['puff_pastry',600,'g'],['ground_veal',300,'g'],['ground_pork',200,'g'],['onion',1,'pc'],['garlic',2,'clove'],['parsley',4,'tbsp'],['white_wine',60,'ml'],['egg_yolk',1,'pc'],['nutmeg',1,'pinch'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Hachez les viandes au couteau plutôt qu'au robot : la farce doit rester en grains distincts et non en pâte.","Mêlez-les à l'oignon râpé, à l'ail, au persil, au vin blanc, à la muscade, au sel et à beaucoup de poivre, et laissez reposer 4 heures au froid.","Abaissez la pâte à 2 mm et découpez des ovales : le feuilletage doit être fin, car il gonfle beaucoup à la cuisson.","Déposez la farce crue sur une moitié, humectez le bord, repliez et soudez en pinçant fermement — la moindre fuite vide le pastel de son jus.","Dorez au jaune et enfournez 25 minutes à 200 °C. Se mangent tièdes, dans l'heure : refroidis, ils perdent le croustillant qui fait tout."],
     en:["Chop the meats with a knife rather than a processor: the filling must stay in distinct grains, not a paste.","Mix them with grated onion, garlic, parsley, white wine, nutmeg, salt and plenty of pepper, and rest for 4 hours in the cold.","Roll the pastry to 2 mm and cut ovals: it must be thin, because it puffs a great deal.","Set the raw filling on one half, damp the edge, fold and seal by pinching firmly — the least leak empties the pastel of its juices.","Glaze with yolk and bake for 25 minutes at 200°C. Eaten warm, within the hour: cold, they lose the crispness that is the whole point."]} },

{ id:'bola-de-lamego', c:'eu', lat:41.096, lon:-7.809, base:8, prep:120, cook:45, diff:2, tags:['pork','bake','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'flat',food:['#e0b45a','#c9924a','#8f5a3a','#f2dfa8'],garnish:'#7fae6a'},
  n:{fr:'Bola de Lamego',en:'Bola de Lamego'},
  p:{fr:'Lamego, Douro, Portugal',en:'Lamego, Douro, Portugal'},
  d:{fr:"Un pain plat fourré de presunto, de chouriço et de lard, cuit en une galette dorée et coupée en carrés. C'est le casse-croûte des vendanges du Douro : il se transporte, se mange froid, et tient un homme jusqu'au soir.",
     en:"A flat bread filled with presunto, chouriço and bacon, baked as a golden slab and cut into squares. This is the Douro harvest snack: it travels, it is eaten cold, and it keeps a man going until evening."},
  i:[['flour',600,'g'],['fresh_yeast',25,'g'],['egg',3,'pc'],['butter',120,'g'],['whole_milk',200,'ml'],['presunto',200,'g'],['chorizo',150,'g'],['smoked_bacon',150,'g'],['olive_oil',40,'ml'],['salt',null,'']],
  s:{fr:["Pétrissez la farine, la levure délayée dans le lait tiède, deux œufs, le beurre mou et le sel 12 minutes, et laissez lever 1 h 30.","Taillez les charcuteries en tranches très fines : en dés, elles perceraient la pâte et laisseraient échapper la graisse.","Divisez la pâte en deux et étalez chaque moitié très mince — 3 mm — sur une plaque huilée.","Couvrez la première d'une seule couche de charcuterie, sans superposer, posez la seconde abaisse et soudez tout le tour en repliant.","Piquez la surface à la fourchette, dorez à l'œuf et cuisez 45 minutes à 190 °C. Laissez tiédir avant de couper en carrés."],
     en:["Knead the flour, the yeast dissolved in warm milk, two eggs, the softened butter and salt for 12 minutes, and prove for 1½ hours.","Slice the charcuterie very thinly: diced, it would pierce the dough and let the fat escape.","Divide the dough in two and roll each half very thin — 3 mm — on an oiled tray.","Cover the first with a single layer of charcuterie, without overlapping, lay the second sheet on and seal all round by folding.","Prick the surface with a fork, glaze with egg and bake for 45 minutes at 190°C. Let it cool before cutting into squares."]} },

{ id:'morcela-de-arganil', c:'eu', lat:40.218, lon:-8.053, base:6, prep:60, cook:60, diff:3, tags:['pork','slow','comfort'],
  art:{v:'plate',bg:'#2b2419',plate:'#f4ecd8',style:'grill',food:['#3a2a2a','#6f2a2a','#e8dcb8','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Morcela d’Arganil',en:'Arganil morcela'},
  p:{fr:'Arganil, Beira Serra, Portugal',en:'Arganil, Beira Serra, Portugal'},
  d:{fr:"Un boudin de la Beira au sang, au cumin et au vin, séché puis fumé lentement au bois de chêne. Contrairement aux boudins du Nord, il ne contient ni riz ni oignon : rien que du sang, de la graisse et des épices, ce qui le rend serré et presque sec à la coupe.",
     en:"A Beira blood sausage with cumin and wine, dried then slowly smoked over oak. Unlike northern black puddings it holds neither rice nor onion: only blood, fat and spice, which makes it tight and almost dry when cut."},
  i:[['pork_blood',1,'l'],['pork_fat',500,'g'],['cumin',2,'tbsp'],['sweet_paprika',2,'tbsp'],['garlic',8,'clove'],['red_wine',200,'ml'],['sausage_casings',null,''],['coarse_salt',40,'g'],['cloves',6,'pc'],['pepper',null,'']],
  s:{fr:["Recueillez le sang en le fouettant aussitôt avec un peu de sel pour l'empêcher de prendre en masse, puis passez-le au tamis.","Taillez le gras en petits dés et faites-le fondre à moitié seulement : entièrement fondu, il ne donnerait plus de mâche.","Pilez l'ail avec le cumin, le paprika, les clous de girofle et le sel, et délayez le tout dans le vin rouge.","Mêlez sang, gras et épices, embossez sans serrer et liez en fers à cheval — l'appareil gonfle en cuisant et un boudin trop plein éclate.","Pochez 40 minutes à 80 °C, sans jamais bouillir, puis séchez trois jours et fumez au chêne une semaine. Se grille ensuite quelques minutes sur les braises."],
     en:["Collect the blood, whisking it at once with a little salt to stop it setting, then pass it through a sieve.","Dice the fat small and render it only halfway: fully rendered, it would give nothing to chew on.","Pound the garlic with the cumin, paprika, cloves and salt, and slake it all in the red wine.","Combine blood, fat and spices, fill the casings loosely and tie them into horseshoes — the mixture swells as it cooks and an overfull sausage bursts.","Poach for 40 minutes at 80°C, never boiling, then dry for three days and smoke over oak for a week. Grill for a few minutes on the coals to serve."]} },

{ id:'bucho-de-arganil', c:'eu', lat:40.222, lon:-8.056, base:8, prep:90, cook:210, diff:3, tags:['pork','slow','festive'],
  art:{v:'board',bg:'#2b2419',plate:'#f0e4c8',style:'other',food:['#8f5a3a','#c9924a','#e8dcb8','#6f4a2a'],garnish:'#7fae6a'},
  n:{fr:'Bucho d’Arganil',en:'Arganil bucho'},
  p:{fr:'Arganil, Beira Serra, Portugal',en:'Arganil, Beira Serra, Portugal'},
  d:{fr:"Une panse de porc farcie de viandes et de pain, cousue et bouillie trois heures, plat du jour de l'abattage à la Noël. Il se sert en tranches épaisses avec les légumes du cozido, et une part de la farce est toujours réservée aux voisins venus aider.",
     en:"A pig's stomach stuffed with meats and bread, sewn shut and boiled for three hours, the dish of slaughter day at Christmas. It is served in thick slices with the cozido vegetables, and a share of the filling always goes to the neighbours who came to help."},
  i:[['pork_stomach',1,'pc'],['pork_shoulder',600,'g'],['pork_belly',300,'g'],['chorizo',200,'g'],['bread',300,'g'],['egg',3,'pc'],['sweet_paprika',2,'tbsp'],['garlic',8,'clove'],['white_wine',200,'ml'],['cumin',1,'tbsp'],['collard_greens',500,'g'],['potato',800,'g'],['salt',null,''],['pepper',null,'']],
  s:{fr:["Retournez la panse et grattez-la à l'eau vinaigrée, puis laissez-la tremper 12 heures en changeant l'eau trois fois.","Taillez les viandes en dés d'un centimètre et faites-les mariner une nuit à l'ail, au paprika, au cumin et au vin blanc.","Ajoutez le pain rassis émietté et les œufs battus : le pain absorbe le jus qui, sans lui, ferait éclater la panse.","Emplissez la panse aux deux tiers seulement et cousez-la à l'aiguille avec du fil de cuisine, en points serrés.","Pochez 3 heures à l'eau frémissante en piquant la panse à l'aiguille au bout de 20 minutes pour chasser l'air. Ajoutez chou et pommes de terre dans le bouillon pour la dernière demi-heure."],
     en:["Turn the stomach inside out and scrape it in vinegared water, then soak it for 12 hours, changing the water three times.","Cut the meats into one-centimetre dice and marinate them overnight with garlic, paprika, cumin and white wine.","Add the crumbled stale bread and beaten eggs: the bread soaks up the juices which, without it, would burst the stomach.","Fill the stomach only two-thirds full and sew it up with kitchen thread in close stitches.","Poach for 3 hours in barely simmering water, pricking the stomach with a needle after 20 minutes to release the air. Add the greens and potatoes to the broth for the last half hour."]} },

{ id:'queijada-da-graciosa', c:'eu', lat:39.086, lon:-28.003, base:12, prep:40, cook:25, diff:2, tags:['sweet','bake','comfort'],
  art:{v:'board',bg:'#33291f',plate:'#f4ead4',style:'pastry',food:['#e8c46a','#f2dfa8','#f4f0e6','#c9924a'],garnish:'#c9754a'},
  n:{fr:'Queijadas da Graciosa',en:'Graciosa queijadas'},
  p:{fr:'Santa Cruz da Graciosa, Açores, Portugal',en:'Santa Cruz da Graciosa, Azores, Portugal'},
  d:{fr:"De petits gâteaux aux jaunes d'œufs et au lait, sans fromage malgré leur nom, cuits dans des caissettes de papier plissé. La Graciosa n'a pas de fromage frais à revendre : ses queijadas se font au beurre et à la fécule, et gonflent en dôme fendu.",
     en:"Small cakes of egg yolk and milk, with no cheese despite the name, baked in pleated paper cases. Graciosa has no fresh cheese to spare: its queijadas are made with butter and starch, and rise into a split dome."},
  i:[['egg_yolk',8,'pc'],['sugar',300,'g'],['whole_milk',250,'ml'],['butter',80,'g'],['cornstarch',60,'g'],['flour',40,'g'],['lemon_zest',1,'pc'],['cinnamon',1,'tsp'],['salt',null,'']],
  s:{fr:["Faites tiédir le lait avec le beurre, le zeste et une pincée de sel, sans le faire bouillir.","Fouettez les jaunes avec le sucre jusqu'à ce que le mélange blanchisse et forme un ruban.","Ajoutez la fécule et la farine tamisées, puis le lait tiède en filet, en fouettant sans arrêt.","Laissez reposer l'appareil 30 minutes : les bulles doivent remonter, sinon les queijadas s'affaissent en refroidissant.","Emplissez les caissettes aux trois quarts et cuisez 25 minutes à 190 °C. Le dessus doit se fendre : c'est la marque de la Graciosa."],
     en:["Warm the milk with the butter, zest and a pinch of salt, without letting it boil.","Whisk the yolks with the sugar until pale and ribboning.","Add the sifted cornstarch and flour, then the warm milk in a stream, whisking constantly.","Rest the batter for 30 minutes: the bubbles must rise, otherwise the queijadas sink as they cool.","Fill the cases three-quarters full and bake for 25 minutes at 190°C. The tops must split: that is the Graciosa mark."]} },

{ id:'alcatra-terceirense', c:'eu', lat:38.656, lon:-27.221, base:6, prep:30, cook:270, diff:2, tags:['beef','slow','sunday'],
  art:{v:'pot',bg:'#2b2419',plate:'#f0e4c8',style:'stew',food:['#6f2a2a','#8f3b2a','#e8dcb8','#c9924a'],garnish:'#7fae6a'},
  n:{fr:'Alcatra',en:'Alcatra'},
  p:{fr:'Angra do Heroísmo, Terceira, Açores, Portugal',en:'Angra do Heroísmo, Terceira, Azores, Portugal'},
  d:{fr:"Du bœuf mijoté quatre heures dans un pot de terre de Vila Franca, au vin de cheiro et au piment de la Jamaïque. Le pot n'est pas un détail : sa terre non vernissée à l'intérieur laisse s'évaporer lentement et concentre la sauce sans jamais la faire attacher.",
     en:"Beef stewed four hours in a Vila Franca clay pot, with vinho de cheiro and allspice. The pot is not a detail: its unglazed interior lets moisture escape slowly and concentrates the sauce without ever catching."},
  i:[['beef_shank',1.5,'kg'],['smoked_bacon',200,'g'],['onion',600,'g'],['garlic',8,'clove'],['red_wine',700,'ml'],['allspice',15,'pc'],['bay_leaf',3,'pc'],['butter',60,'g'],['black_peppercorns',1,'tbsp'],['bread',400,'g'],['salt',null,'']],
  s:{fr:["Frottez l'intérieur du pot de terre de lard, puis tapissez le fond d'oignons en rondelles épaisses.","Rangez la viande en gros morceaux, l'ail, le piment de la Jamaïque entier et le laurier, et couvrez d'une seconde couche d'oignons.","Versez le vin rouge jusqu'à hauteur, ajoutez le beurre, salez, et n'ajoutez surtout pas d'eau : l'oignon en rendra assez.","Enfournez à couvert 4 heures à 150 °C, sans jamais remuer ni découvrir avant la troisième heure.","Découvrez la dernière demi-heure pour laisser la sauce réduire et la surface se colorer. Servez avec du pain doux de l'île."],
     en:["Rub the inside of the clay pot with bacon, then line the base with thickly sliced onions.","Lay in the meat in large pieces, the garlic, the whole allspice and the bay, and cover with a second layer of onions.","Pour in red wine to cover, add the butter, salt, and on no account add water: the onions will give enough.","Bake covered for 4 hours at 150°C, never stirring or lifting the lid before the third hour.","Uncover for the last half hour to let the sauce reduce and the surface colour. Serve with the island's sweet bread."]} },

{ id:'torresmos-transmontanos', c:'eu', lat:41.539, lon:-6.958, base:6, prep:30, cook:120, diff:2, tags:['pork','slow','comfort'],
  art:{v:'plate',bg:'#33291f',plate:'#f4ecd8',style:'grill',food:['#c9924a','#8f5a3a','#e0b45a','#f0e8d0'],garnish:'#7fae6a'},
  n:{fr:'Torresmos',en:'Torresmos'},
  p:{fr:'Macedo de Cavaleiros, Trás-os-Montes, Portugal',en:'Macedo de Cavaleiros, Trás-os-Montes, Portugal'},
  d:{fr:"Des morceaux de poitrine de porc confits dans leur propre graisse puis remontés à feu vif jusqu'à ce que la couenne éclate. Ils sont le sous-produit du jour de l'abattage : on fondait le saindoux pour l'année, et ce qui restait dans le chaudron était le repas du soir.",
     en:"Pieces of pork belly confited in their own fat then finished over high heat until the rind blisters. They are the by-product of slaughter day: the lard was rendered for the year, and what stayed in the cauldron was that evening's meal."},
  i:[['pork_belly',1.5,'kg'],['lard',200,'g'],['garlic',8,'clove'],['sweet_paprika',2,'tbsp'],['white_wine',200,'ml'],['bay_leaf',3,'pc'],['coarse_salt',40,'g'],['cornmeal',300,'g'],['orange',3,'pc'],['pepper',null,'']],
  s:{fr:["Taillez la poitrine en cubes de 4 cm avec la couenne, et faites-les mariner 12 heures à l'ail pilé, au paprika, au vin blanc et au sel.","Égouttez-les et épongez-les : de la marinade restée sur la viande ferait crépiter dangereusement la graisse.","Confisez-les 1 h 30 dans le saindoux à 90 °C, à découvert, sans jamais frémir — c'est une cuisson douce, pas une friture.","Ils sont prêts quand une brochette traverse la couenne sans résistance. Sortez-les et laissez-les tiédir 20 minutes.","Remontez la graisse à 190 °C et replongez-les 4 minutes pour faire éclater la couenne. Servez avec une bouillie de maïs et des quartiers d'orange, dont l'acidité coupe le gras."],
     en:["Cut the belly into 4 cm cubes with the rind on, and marinate them 12 hours with crushed garlic, paprika, white wine and salt.","Drain and pat them dry: marinade left on the meat would make the fat spit dangerously.","Confit them for 1½ hours in lard at 90°C, uncovered, never simmering — this is gentle cooking, not frying.","They are ready when a skewer passes through the rind without resistance. Lift them out and let them cool for 20 minutes.","Bring the fat to 190°C and return them for 4 minutes to blister the rind. Serve with cornmeal porridge and orange quarters, whose acidity cuts the fat."]} },

{ id:'arroz-de-lingueirao', c:'eu', lat:37.126, lon:-7.649, base:4, prep:40, cook:30, diff:2, tags:['sea','rice','comfort'],
  art:{v:'pot',bg:'#26485c',plate:'#f0e4c8',style:'rice',food:['#e8dcb8','#f0e8d0','#7fae5a','#c9402c'],garnish:'#6fbf8f'},
  n:{fr:'Arroz de lingueirão',en:'Razor clam rice'},
  p:{fr:'Tavira, Algarve, Portugal',en:'Tavira, Algarve, Portugal'},
  d:{fr:"Un riz humide aux couteaux de mer, ramassés dans le sable de la ria Formosa en versant du sel dans leur trou. Le sel imite la marée montante et le coquillage remonte de lui-même : c'est la seule façon de le prendre entier.",
     en:"A wet rice with razor clams, gathered from the sand of the Ria Formosa by pouring salt into their hole. The salt mimics the rising tide and the clam comes up by itself: the only way to take it whole."},
  i:[['razor_clams',1,'kg'],['long_grain_rice',250,'g'],['onion',1,'pc'],['garlic',4,'clove'],['ripe_tomato',300,'g'],['red_pepper',1,'pc'],['white_wine',150,'ml'],['olive_oil',80,'ml'],['cilantro',1,'bunch'],['piri_piri',1,'tsp'],['bay_leaf',2,'pc'],['salt',null,'']],
  s:{fr:["Faites dégorger les couteaux 2 heures en eau salée, puis ouvrez-les à la vapeur en 90 secondes et gardez tout le jus.","Retirez la chair, ôtez la poche noire et coupez le pied en tronçons ; réservez quelques coquilles pour le dressage.","Faites un refogado d'oignon, d'ail et de poivron à l'huile d'olive, longuement, puis ajoutez la tomate râpée et laissez confire.","Nacrez le riz, mouillez de vin blanc puis du jus filtré des coquillages complété d'eau — trois volumes pour un de riz : ce riz doit rester coulant.","Cuisez 14 minutes, ajoutez les couteaux et la coriandre hors du feu, et servez immédiatement dans le poêlon."],
     en:["Purge the razor clams for 2 hours in salted water, then steam them open in 90 seconds and keep every drop of liquor.","Take out the flesh, remove the dark sac and cut the foot into lengths; keep a few shells for serving.","Make a long refogado of onion, garlic and pepper in olive oil, then add grated tomato and let it melt down.","Pearl the rice, moisten with white wine then the strained clam liquor made up with water — three parts to one of rice: this rice must stay soupy.","Cook for 14 minutes, add the clams and coriander off the heat, and serve at once in the pan."]} },

{ id:'bacalhau-a-minhota', c:'eu', lat:41.545, lon:-8.426, base:4, prep:40, cook:35, diff:2, tags:['sea','fry','comfort'],
  art:{v:'plate',bg:'#33301f',plate:'#f4ecd8',style:'fish',food:['#f0e8d0','#e0b45a','#c9924a','#7fae5a'],garnish:'#7fae6a'},
  n:{fr:'Bacalhau à minhota',en:'Bacalhau à minhota'},
  p:{fr:'Braga, Minho, Portugal',en:'Braga, Minho, Portugal'},
  d:{fr:"Une posta de morue farinée et frite, couchée sur des rondelles de pommes de terre et d'oignons frits, le tout noyé d'huile d'olive et passé au four. Le Minho ne pose jamais la morue sur des pommes de terre bouillies : elles doivent avoir été frites, pour tenir sous l'huile.",
     en:"A thick cod loin floured and fried, laid on rounds of fried potato and onion, all flooded with olive oil and finished in the oven. The Minho never sets its cod on boiled potatoes: they must have been fried, to hold up under the oil."},
  i:[['salt_cod',800,'g'],['potato',1,'kg'],['onion',3,'pc'],['garlic',6,'clove'],['flour',80,'g'],['olive_oil',250,'ml'],['bay_leaf',2,'pc'],['parsley',4,'tbsp'],['frying_oil',600,'ml'],['pepper',null,'']],
  s:{fr:["Dessalez la morue 36 heures au réfrigérateur, peau vers le haut, en changeant l'eau quatre fois — les postes épaisses demandent plus de temps que les miettes.","Épongez-les, farinez-les et faites-les frire 4 minutes par face dans l'huile chaude, jusqu'à une croûte blonde.","Frites séparément, en rondelles épaisses, les pommes de terre doivent rester fermes et l'oignon devenir translucide sans brunir.","Rangez pommes de terre et oignons au fond d'un plat de terre, posez la morue dessus et couvrez d'ail émincé et de laurier.","Arrosez généreusement d'huile d'olive et passez 15 minutes à 200 °C. L'huile ne se jette pas : on la sauce au pain."],
     en:["Desalt the cod for 36 hours in the fridge, skin up, changing the water four times — thick loins need longer than flakes.","Pat them dry, flour them and fry 4 minutes a side in hot oil, to a pale gold crust.","Fried separately in thick rounds, the potatoes must stay firm and the onion turn translucent without browning.","Arrange potatoes and onions in the base of an earthenware dish, set the cod on top and cover with sliced garlic and bay.","Douse generously with olive oil and give it 15 minutes at 200°C. The oil is not thrown away: it is mopped up with bread."]} }
];
